const input = $input.first().json;
const clean = (v, max) => String(v ?? '').replace(/[\u0000-\u001F\u007F]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
const customer_name = clean(input.customer_name, 200);
const customer_email = clean(input.customer_email, 254).toLowerCase();
const company = clean(input.company, 200);
const subject = clean(input.subject, 300);
const original_message = String(input.message ?? '').replace(/\r/g, '').trim().slice(0, 5000);
const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(customer_email);
const problems = [];
if (!customer_name) problems.push('name missing');
if (!emailOk) problems.push('email invalid');
if (!subject) problems.push('subject missing');
if (!original_message) problems.push('message missing');
const now = new Date();
const stamp = now.toISOString().slice(0, 10).replace(/-/g, '');
const enquiry_id = 'ENQ-' + stamp + '-' + $execution.id;
return [{ json: {
  enquiry_id,
  received_at: now.toISOString(),
  customer_name,
  customer_email,
  company,
  subject,
  original_message,
  processing_status: problems.length ? 'Invalid Input - Not Processed' : 'Received',
  input_valid: problems.length === 0,
  validation_error: problems.join('; ')
} }];

const original = $('02 - Normalise and Assign ID').first().json;
const response = $input.first().json;
const choice = (response.choices || [])[0];
if (!choice || !choice.message) throw new Error('DeepSeek returned no choices for ' + original.enquiry_id);
if (choice.finish_reason && choice.finish_reason !== 'stop') {
  throw new Error('DeepSeek output stopped early (finish_reason: ' + choice.finish_reason + ') for ' + original.enquiry_id);
}
const rawText = choice.message.content;
if (!rawText || !String(rawText).trim()) throw new Error('DeepSeek returned no text for ' + original.enquiry_id);
let parsed;
try {
  parsed = JSON.parse(String(rawText).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, ''));
} catch (e) {
  throw new Error('DeepSeek output is not valid JSON for ' + original.enquiry_id + ': ' + e.message);
}
const cats = ['Sales', 'Support', 'Billing', 'General', 'Spam'];
const urgs = ['High', 'Medium', 'Low'];
if (!cats.includes(parsed.category)) throw new Error('Invalid category for ' + original.enquiry_id);
if (!urgs.includes(parsed.urgency)) throw new Error('Invalid urgency for ' + original.enquiry_id);
if (typeof parsed.confidence !== 'number' || parsed.confidence < 0 || parsed.confidence > 1) throw new Error('Invalid confidence for ' + original.enquiry_id);
if (typeof parsed.special_attention !== 'boolean') throw new Error('Invalid special_attention for ' + original.enquiry_id);
if (typeof parsed.draft_reply !== 'string' || !parsed.draft_reply.trim()) throw new Error('Missing draft reply for ' + original.enquiry_id);
if (parsed.draft_reply.length > 4000) throw new Error('Draft reply too long for ' + original.enquiry_id);
return [{ json: {
  ...original,
  ai_category: parsed.category,
  ai_urgency: parsed.urgency,
  ai_confidence: parsed.confidence,
  ai_reasoning: String(parsed.reasoning ?? '').slice(0, 2000),
  enquiry_summary: String(parsed.enquiry_summary ?? '').slice(0, 1000),
  ai_draft_reply: parsed.draft_reply,
  special_attention: parsed.special_attention,
  processing_status: 'Classified - Awaiting Human Review',
  approval_decision: 'Pending',
  email_delivery_status: 'Not Sent'
} }];

const base = $('07 - Validate AI Output').first().json;
const resp = $input.first().json;
const data = resp.data ?? resp;
let decision;
if (data && data.approved === true) decision = 'Approved';
else if (data && data.approved === false) decision = 'Rejected';
else if (!data || Object.keys(data).length === 0) decision = 'Expired';
else decision = 'Unclear';
return [{ json: {
  ...base,
  approval_decision: decision,
  approval_response: JSON.stringify(data ?? {}),
  approval_timestamp: new Date().toISOString(),
  processing_status: decision === 'Approved' ? 'Approved - Sending Reply' : 'Not Approved - Not Sent'
} }];

const base = $('10 - Record Human Decision').first().json;
const sent = $input.first().json;
return [{ json: {
  ...base,
  email_delivery_status: 'Sent',
  gmail_message_id: sent.id || '',
  processing_status: 'Completed - Reply Sent',
  completed_at: new Date().toISOString()
} }];

const base = $('10 - Record Human Decision').first().json;
const map = {
  Rejected: 'Completed - Rejected by Reviewer',
  Expired: 'Completed - Approval Expired',
  Unclear: 'Completed - Unclear Decision, Not Sent'
};
return [{ json: {
  ...base,
  email_delivery_status: 'Not Sent',
  processing_status: map[base.approval_decision] || 'Completed - Not Sent',
  completed_at: new Date().toISOString()
} }];

const base = $('02 - Normalise and Assign ID').first().json;
const err = $input.first().json;
const reason = (err.error && err.error.message) || err.message || 'Unknown AI failure';
return [{ json: {
  enquiry_id: base.enquiry_id,
  received_at: base.received_at,
  customer_name: base.customer_name,
  customer_email: base.customer_email,
  company: base.company,
  subject: base.subject,
  original_message: base.original_message,
  processing_status: 'AI Failed - Needs Manual Handling',
  approval_decision: 'Not Reached',
  email_delivery_status: 'Not Sent',
  completed_at: new Date().toISOString(),
  failure_detail: reason
} }];

const base = $('10 - Record Human Decision').first().json;
const err = $input.first().json;
const reason = (err.error && err.error.message) || err.message || 'Unknown send failure';
return [{ json: {
  ...base,
  email_delivery_status: 'Send Error',
  processing_status: 'Approved - Sending Failed',
  completed_at: new Date().toISOString(),
  failure_detail: reason
} }];
